  "privFooter": "Privacy at storage",
  "privTitle": "Privacy at storage ng browser",
  "privClose": "Isara ang abiso sa privacy",
  "privWho": "Sino ang responsable?",
  "privWhat": "Ano ang ginagamit namin at bakit",
  "privStorage": "Storage ng browser",
  "privOther": "Iba pang kasalukuyang feature",
  "privProviders": "Mga service provider at internasyonal na paglilipat",
  "privRetention": "Pagtatago at pagbura",
  "privRights": "Ang iyong mga karapatan",
  "noticeReopen": "Abiso sa storage",
  "noticeLabel": "Abiso sa storage ng browser",
  "noticeText": "Gumagamit ang Cook ng storage ng browser para sa mga feature sa pagluluto at pag-sign in na ginagamit mo. Walang idinadagdag na storage para sa ads o analytics.",
  "noticeClose": "Isara ang abiso sa storage",
  "privDraftLabel": "Draft — na-update noong Oktubre 28, 2026.",
  "privDraft": "Kasalukuyang sinusubukan ang mga feature ng account. Dapat kumpletuhin ang mga detalye ng operator at serbisyo sa ibaba bago ang pampublikong paglulunsad.",
  "privWho1": "Ang Cook ay pinapatakbo ng [legal na pangalan at postal address ng operator]. Makipag-ugnayan sa [email address para sa privacy] para sa mga tanong at kahilingan tungkol sa privacy. Dapat kumpletuhin ang mga detalyeng ito bago buksan ang pagpaparehistro.",
  "privWhat1": "Kapag gumawa ka ng account, ginagamit namin ang iyong email, isang account identifier, mga rekord ng password authentication at verification status para maibigay at maprotektahan ang iyong account. Hinahawakan ng authentication provider ang mga password bilang secure na hash; hindi nag-iimbak ang Cook ng nababasang password. Iniimbak namin ang ayos ng kusina, napiling wika, tema at mga unit ng sukat para maibalik ang iyong mga setting sa lahat ng device. Kailangan ang email at password para sa account; puwede kang tumingin ng mga recipe kahit walang account.",
  "privWhat2": "Kailangan ang pagproseso ng account at mga setting para maibigay ang serbisyong account na hinihiling mo (GDPR Artikulo 6(1)(b)). Maaaring iproseso ang limitadong rekord para sa seguridad at pag-iwas sa pang-aabuso batay sa lehitimong interes (Artikulo 6(1)(f)), ayon sa pangangailangan at pagtitimbang. Ang mga email para sa verification at pag-reset ng password ay mensahe ng serbisyo, hindi marketing. Walang idinadagdag na advertising o analytics ang feature ng account.",
  "privStorage1": "Gumagamit ang Cook ng sessionStorage para madala ang iyong kusina, progreso sa pagluluto at mga pinili sa pagitan ng mga pahina sa iisang tab. Kapag naka-sign in ka, hawak din nito ang iyong authentication session. Karaniwang binubura ito ng browser kapag natapos ang session ng tab, pero maaari itong manatili dahil sa session restore ng browser. Binubura ng pag-sign out ang tab data ng Cook. Ang pagsara sa abiso sa storage ay naaalala lang sa tab na iyon. Hindi naglalagay ng cookie ang sariling mga script ng Cook. Maaaring may sariling security processing ang iyong hosting o service provider na dapat maidokumento bago ang paglulunsad.",
  "privStorage2": "Ang OK at ang close button sa abiso sa storage ay nagsasara lang ng abiso. Hindi nito pinapayagan ang analytics, advertising o iba pang opsyonal na pagsubaybay. Anumang hindi mahalagang storage sa hinaharap ay mangangailangan ng hiwalay na pagpili bago ito magsimula, na kasindali ring tanggihan at bawiin.",
  "privOther1": "Ang kasalukuyang voice feature ng listahan ng recipe ay humihingi sa country.is ng tinatayang bansa batay sa iyong IP address para pumili ng wika sa speech recognition. Kung gagamit ka ng microphone recognition, maaaring ipadala ng browser ang audio sa sarili nitong speech-service provider. Puwede mo ring i-type ang mga sangkap. Dapat suriin ang mga provider na ito, ang kanilang mga patakaran at ang legal na batayan ng mga feature na ito bago ang pampublikong paglulunsad.",
  "privProviders1": "Nakaplanong account provider: Supabase (managed PostgreSQL at authentication), gamit ang napiling database region sa EU. Email provider: [provider]. Website host: [provider]. Dapat kumpirmahin ng operator ang aktwal na mga provider, mga kasunduan sa pagproseso, mga subprocessor, lokasyon ng mga log at anumang paglilipat palabas ng EEA. Ang database region sa EU ay hindi mismong nag-aalis ng posibilidad ng internasyonal na paglilipat. Kung naaangkop, tukuyin ang naaangkop na adequacy decision o mga kontraktwal na pananggalang at kung paano makakakuha ng kopya.",
  "privRetention1": "Itinatago ang mga setting ng account habang aktibo ang iyong account. Puwede kang humiling ng pagbura sa pamamagitan ng privacy contact sa itaas. Bago ang paglulunsad, dapat tukuyin ng operator ang proseso ng pagtugon sa mga kahilingan sa pagbura, ang pag-expire ng mga hindi na-verify na account, at ang tagal ng pagtatago ng mga security log at backup. Maaaring manatili ang binurang data sa mga backup na may limitadong access hanggang matapos ang nakadokumentong panahon ng pagtatago.",
  "privRights1": "Depende sa mga naaangkop na kondisyon, puwede kang humiling ng access, pagwawasto, pagbura, paghihigpit o portability, o tumutol sa pagprosesong batay sa lehitimong interes. Makipag-ugnayan sa operator sa itaas; karaniwang sinasagot ang mga kahilingan sa loob ng isang buwan, at ipinapaliwanag ang anumang legal na extension. Puwede kang magreklamo sa iyong supervisory authority, kasama ang NAIH ng Hungary sa naih.hu. Hindi ginagamit ng Cook ang mga setting ng account para sa mga awtomatikong desisyon na may legal o katulad na makabuluhang epekto.",
